package fr.cercle.tourderole;
import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.widget.*;import android.view.*;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;import javax.xml.parsers.*;import org.w3c.dom.*;
public class Reader{static Reader active;public static void saveActive(MainActivity a){if(active!=null&&active.a==a)active.save();}public static void closeActive(MainActivity a){if(active!=null&&active.a==a&&active.dialog!=null)active.dialog.dismiss();}
final MainActivity a;final JSONObject record;File file;PdfRenderer pdf;ParcelFileDescriptor fd;ZipFile zip;ArrayList<String> pages=new ArrayList<>();boolean epub;int pos,font,zoom=1;boolean night;Dialog dialog;LinearLayout root;ScrollView scroll;ImageView image;Bitmap bitmap;TextView text,status;
Reader(MainActivity app,JSONObject r)throws Exception{a=app;record=r;file=a.file(r.optString("_file"));String name=r.optString("_label").toLowerCase(Locale.ROOT);if(name.endsWith(".pdf")){fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);pdf=new PdfRenderer(fd);if(pdf.getPageCount()==0)throw new IOException("PDF vide");}else if(name.endsWith(".epub")||name.endsWith(".cbz")||name.endsWith(".zip")){zip=new ZipFile(file);if(zip.size()>10000)throw new IOException("Archive trop complexe");epub=name.endsWith(".epub");if(epub)epub();else{Enumeration<? extends ZipEntry> en=zip.entries();while(en.hasMoreElements()){ZipEntry e=en.nextElement();if(!e.isDirectory()&&e.getName().toLowerCase(Locale.ROOT).matches(".*\\.(jpg|jpeg|png|webp)"))pages.add(e.getName());}Collections.sort(pages,Core::natural);}if(pages.isEmpty())throw new IOException("Aucun contenu lisible. Vérifie le format et l’absence de DRM.");}else throw new IOException("Choisis un EPUB, PDF ou CBZ.");pos=Math.max(0,Math.min(count()-1,r.optInt("_pos")));font=Math.max(14,Math.min(34,r.optInt("_font",20)));night=r.optBoolean("_night");}
int count(){return pdf==null?pages.size():pdf.getPageCount();}
public static void open(MainActivity a,JSONObject r){try{Reader reader=new Reader(a,r);reader.show();}catch(Exception e){a.error(e);}}
static Document xml(byte[] bytes)throws Exception{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);f.setXIncludeAware(false);f.setExpandEntityReferences(false);return f.newDocumentBuilder().parse(new ByteArrayInputStream(bytes));}
byte[] entry(String name,int max)throws Exception{ZipEntry e=zip.getEntry(name);if(e==null)throw new IOException("Élément EPUB absent : "+name);return MainActivity.read(zip.getInputStream(e),max);}
org.xmlpull.v1.XmlPullParser parser(byte[] bytes)throws Exception{String raw=new String(bytes,"UTF-8");if(raw.contains("<!DOCTYPE")||raw.contains("<!ENTITY"))throw new IOException("Cet EPUB contient une déclaration DTD non prise en charge.");org.xmlpull.v1.XmlPullParser p=android.util.Xml.newPullParser();p.setFeature(org.xmlpull.v1.XmlPullParser.FEATURE_PROCESS_NAMESPACES,true);p.setInput(new ByteArrayInputStream(bytes),"UTF-8");return p;}
void epub()throws Exception{org.xmlpull.v1.XmlPullParser p=parser(entry("META-INF/container.xml",200000));String opf=null;while(p.next()!=org.xmlpull.v1.XmlPullParser.END_DOCUMENT)if(p.getEventType()==org.xmlpull.v1.XmlPullParser.START_TAG&&p.getName().equals("rootfile")){opf=p.getAttributeValue(null,"full-path");break;}if(opf==null||opf.startsWith("/")||opf.contains(".."))throw new IOException("Structure EPUB non reconnue");p=parser(entry(opf,2000000));HashMap<String,String> items=new HashMap<>();ArrayList<String> spine=new ArrayList<>();while(p.next()!=org.xmlpull.v1.XmlPullParser.END_DOCUMENT){if(p.getEventType()!=org.xmlpull.v1.XmlPullParser.START_TAG)continue;if(p.getName().equals("item")){String href=p.getAttributeValue(null,"href"),id=p.getAttributeValue(null,"id");if(href==null||id==null)continue;java.net.URI resolved=new java.net.URI(opf).resolve(href).normalize();if(resolved.isAbsolute()||resolved.getPath().startsWith("../"))throw new IOException("Ressource externe EPUB refusée");items.put(id,resolved.getPath());}if(p.getName().equals("itemref"))spine.add(p.getAttributeValue(null,"idref"));}for(String id:spine){String href=items.get(id);if(href!=null)pages.add(href);}}

void show(){active=this;dialog=new Dialog(a);root=a.col();root.setPadding(a.dp(8),a.dp(8),a.dp(8),a.dp(8));status=a.text("",16,a.paper);root.addView(status);a.horizontalButtons(root,a.button("←",()->go(-1)),a.button("Favori",this::bookmark),a.button("→",()->go(1)));a.horizontalButtons(root,a.button(epub?"Texte −":"Zoom −",()->{if(epub)font=Math.max(14,font-2);else zoom=1;draw();}),a.button(epub?"Texte +":"Zoom +",()->{if(epub)font=Math.min(34,font+2);else zoom=2;draw();}),a.button("Thème",()->{night=!night;draw();}),a.button("Favoris",this::marks));scroll=new ScrollView(a);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));a.addButton(root,"Fermer la lecture",()->dialog.dismiss());dialog.setContentView(root);dialog.setOnDismissListener(d->{save();active=null;if(image!=null)image.setImageBitmap(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}try{if(pdf!=null)pdf.close();if(fd!=null)fd.close();if(zip!=null)zip.close();}catch(Exception ignored){}});dialog.show();dialog.getWindow().setLayout(-1,-1);draw();}
void save(){try{record.put("_pos",pos);record.put("_font",font);record.put("_night",night);if(epub&&scroll!=null)record.put("_scroll",scroll.getScrollY());a.save();}catch(Exception e){a.error(e);}}
void go(int delta){if(pos+delta<0||pos+delta>=count())return;pos+=delta;record.remove("_scroll");draw();}
void draw(){try{root.setBackgroundColor(night?a.ink:Color.rgb(245,238,216));status.setText((pos+1)+" / "+count()+" · "+Math.round((pos+1)*100f/count())+" %");status.setTextColor(night?a.paper:a.ink);scroll.removeAllViews();if(epub){String html=new String(entry(pages.get(pos),3*1024*1024),"UTF-8");text=a.text(android.text.Html.fromHtml(html,android.text.Html.FROM_HTML_MODE_LEGACY).toString(),font,night?a.paper:a.ink);text.setTextIsSelectable(true);text.setLineSpacing(a.dp(5),1.15f);scroll.addView(text);int y=record.optInt("_scroll");scroll.post(()->scroll.scrollTo(0,y));}else{if(bitmap!=null){bitmap.recycle();bitmap=null;}if(pdf!=null){try(PdfRenderer.Page page=pdf.openPage(pos)){int width=Math.min(2200,a.getResources().getDisplayMetrics().widthPixels*zoom),height=(int)(page.getHeight()*(width/(float)page.getWidth()));if(height>4200){width=(int)(width*4200f/height);height=4200;}bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);}}else{BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;try(InputStream bounds=zip.getInputStream(zip.getEntry(pages.get(pos)))){BitmapFactory.decodeStream(bounds,null,opt);}opt.inSampleSize=Math.max(1,Math.max(opt.outWidth,opt.outHeight)/(1600*zoom));opt.inJustDecodeBounds=false;try(InputStream in=zip.getInputStream(zip.getEntry(pages.get(pos)))){bitmap=BitmapFactory.decodeStream(in,null,opt);}if(bitmap==null)throw new IOException("Image CBZ non lisible");}image=new ImageView(a);image.setImageBitmap(bitmap);image.setAdjustViewBounds(true);scroll.addView(image,new ScrollView.LayoutParams(zoom==1?-1:bitmap.getWidth(),-2));}record.put("_pos",pos);record.put("_font",font);record.put("_night",night);a.save();}catch(Exception e){a.error(e);}}
void bookmark(){try{JSONArray marks=record.optJSONArray("_marks");if(marks==null)marks=new JSONArray();for(int i=0;i<marks.length();i++)if(marks.optInt(i)==pos){a.toast("Page déjà dans les favoris.");return;}marks.put(pos);record.put("_marks",marks);a.save();a.toast("Favori enregistré.");}catch(Exception e){a.error(e);}}
void marks(){JSONArray marks=record.optJSONArray("_marks");if(marks==null||marks.length()==0){a.toast("Aucun favori.");return;}String[] labels=new String[marks.length()];for(int i=0;i<labels.length;i++)labels[i]="Page / chapitre "+(marks.optInt(i)+1);new AlertDialog.Builder(a).setTitle("Favoris").setItems(labels,(d,n)->{pos=marks.optInt(n);record.remove("_scroll");draw();}).setNegativeButton("Fermer",null).show();}
}
